Ext.define('bcp.controller.AppController', {
    extend: 'Ext.app.Controller',

    listen: {global: {unexpectedBcpError: 'appErrorHandler'}},

    control: {'#reqGrid': {select: 'onReqGridSelect'}},

    onReqGridSelect: function (rowmodel, record, index, eOpts) {
        //Code Refactoring
        //when a row is selected from the request grid, we always want to set the
        //selected record to the model of the container that contains the grid

        //view specific selected logic can be added to the select event of the grid in that
        //view and it will be called first before this event is triggered

        //set current req record to the store
        var store = Ext.getStore('CurrentRequest');
        store.removeAll();
        store.add(record);

        //get the model of the container
        var model = rowmodel.view.lookupViewModel();
        //if found, set record to it
        if (model) {
            //TODO: can do a search in code later to see if one of the duplicate record
            //can be eliminated
            model.set('record', record);
            model.set('generalInfo', record);
            //added code for decide whether to show actual total & approval amount
            var status = record.get('statusCode');

            if (status == 8 || status == 9 || status == 13) {
                model.set('showActual', true);
            } else {
                model.set('showActual', false);
            }

            if (status == 7 || status == 8 || status == 9 || status == 13) {
                model.set('showApprovalAmount', true);
            } else {
                model.set('showApprovalAmount', false);
            }
        }
    },

    appErrorHandler: function (ex) {
        //if needed, place holder for future error handling
        //by firing app level event unexpectedBcpError
    }
});
